package cn.mop.persistence;
import cn.mop.persistence.*;
import cn.mop.persistence.PostgresBackupArchiveRepository.*;
import cn.mop.domain.DomainException;
import cn.mop.domain.backup.BackupArchivePayload;
import cn.mop.domain.backup.BackupArchivePayload.Scope;
import cn.mop.adapters.backup.BackupEnvelopeEncryption;
import javax.sql.DataSource;
import org.postgresql.ds.PGSimpleDataSource;
import java.sql.*;import java.lang.reflect.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
@org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable(named="MOP_BACKUP_ARCHIVE_TEST_ENVIRONMENT",matches="dot-backup-archive-disposable")
class BackupArchivePostgresTest {
 @org.junit.jupiter.api.Test void isolatedDatabaseContract()throws Exception{main(new String[0]);}
 static UUID tenant,actor=UUID.randomUUID();static int checks;static AtomicInteger open=new AtomicInteger(),proofs=new AtomicInteger(),envelopes=new AtomicInteger();
 static final String REF="sha256:"+"a".repeat(64);static DataSource tracked;static BackupEnvelopeEncryption cipher;
 static UUID id(){return UUID.randomUUID();}static void check(boolean ok,String label){if(!ok)throw new AssertionError(label);checks++;System.out.println("PASS "+label);}
 interface Attempt{void run()throws Exception;}static void denied(Attempt f,String label)throws Exception{try{f.run();}catch(DomainException e){if(!Set.of(400,403,404,409).contains(e.status))throw e;check(true,label);return;}catch(SQLException e){if(!Set.of("23514","23505","42501").contains(e.getSQLState()))throw e;check(true,label);return;}throw new AssertionError("accepted "+label);}
 static void proofDenied(Attempt f,String label)throws Exception{try{f.run();}catch(DomainException e){if(e.status!=503)throw e;if(e.getMessage().contains("secret-must-not-leak"))throw new AssertionError("proof error leaked");check(true,label);return;}throw new AssertionError("accepted "+label);}
 static Access access(){return new Access(tenant,actor,1);}
 static BackupEnvelopeEncryption.Access cryptoAccess(){return new BackupEnvelopeEncryption.Access(tenant,actor,1);}
 static BackupEnvelopeEncryption.Scope cryptoScope(Scope s){return new BackupEnvelopeEncryption.Scope(s.tenantId(),s.assetId(),s.runId(),s.attemptNumber(),s.versionId());}
 static BackupArchivePayload payload(Scope s){var e=cipher.seal(cryptoAccess(),cryptoScope(s),"SYNTHETIC CONFIGURATION ONLY".getBytes(java.nio.charset.StandardCharsets.UTF_8));return BackupArchivePayload.parse(e.encoded(),e.sha256());}
 static void authenticate(BackupArchivePayload p){check(open.get()==0,"crypto_verification_outside_sql_transaction");cipher.open(cryptoAccess(),cryptoScope(p.scope()),cipher.decode(p.bytes(),p.sha256(),cryptoScope(p.scope())));envelopes.incrementAndGet();}
 static PostgresBackupArchiveRepository repo(){return new PostgresBackupArchiveRepository(tracked,(c,a,s,o)->{if(!tenant.equals(a.tenantId())||a.permissionVersion()!=1)throw new DomainException(403,"REVOKED","synthetic");},(a,p)->authenticate(p),(a,s,p,o,e)->{check(open.get()==0,"evidence_verification_outside_sql_transaction");if(!REF.equals(e))throw new DomainException(503,"UNVERIFIED","secret-must-not-leak");if(o==Action.VERIFY_OBJECT)authenticate(s.payload());proofs.incrementAndGet();});}
 static Scope running()throws Exception{UUID asset=RunDatabaseChecks.asset(),run=id();RunDatabaseChecks.repo().queue(tenant,asset,run,id(),"q");RunDatabaseChecks.repo().start(tenant,asset,run,id(),0,RunDatabaseChecks.acquire(asset,300000),"s");return new Scope(tenant,asset,run,1,id());}
 static long count(String table)throws Exception{try(var c=RunDatabaseChecks.runtime.getConnection();var q=c.createStatement();var r=q.executeQuery("SELECT count(*) FROM "+table)){r.next();return r.getLong(1);}}
 static void rawSource(Connection c,Scope s,BackupArchivePayload p)throws Exception{try(var q=c.prepareStatement("INSERT INTO mop_backup_archive_submission(tenant_id,version_id,asset_id,run_id,attempt_number,run_version,submission_id,submission_sha256,encoded_envelope,envelope_sha256,envelope_bytes,key_reference,created_by) VALUES(?,?,?,?,1,1,?,?,?,?,?,?,?)")){q.setObject(1,tenant);q.setObject(2,s.versionId());q.setObject(3,s.assetId());q.setObject(4,s.runId());q.setObject(5,id());q.setString(6,"a".repeat(64));q.setBytes(7,p.bytes());q.setString(8,p.sha256());q.setInt(9,p.size());q.setString(10,p.keyReference());q.setObject(11,actor);q.executeUpdate();}}
 public static void main(String[] args)throws Exception{
  if(!"dot-backup-archive-disposable".equals(System.getenv("MOP_BACKUP_ARCHIVE_TEST_ENVIRONMENT")))throw new IllegalStateException("Explicit disposable gate required");
  RunDatabaseChecks.runtime=RunDatabaseChecks.source("mop_test_runtime",System.getenv("SPRING_DATASOURCE_PASSWORD"));RunDatabaseChecks.migrator=RunDatabaseChecks.source("mop_test_migrator",System.getenv("MOP_MIGRATION_PASSWORD"));
  try(var c=RunDatabaseChecks.runtime.getConnection();var q=c.createStatement();var r=q.executeQuery("SELECT tenant_id FROM mop_site ORDER BY tenant_id,id LIMIT 1")){r.next();tenant=r.getObject(1,UUID.class);RunDatabaseChecks.tenant=tenant;}
  tracked=(DataSource)Proxy.newProxyInstance(BackupArchivePostgresTest.class.getClassLoader(),new Class[]{DataSource.class},(p,m,a)->{try{Object result=m.invoke(RunDatabaseChecks.runtime,a);if(!m.getName().equals("getConnection"))return result;Connection c=(Connection)result;open.incrementAndGet();AtomicBoolean closed=new AtomicBoolean();return Proxy.newProxyInstance(BackupArchivePostgresTest.class.getClassLoader(),new Class[]{Connection.class},(cp,cm,ca)->{try{return cm.invoke(c,ca);}catch(InvocationTargetException e){throw e.getCause();}finally{if(cm.getName().equals("close")&&closed.compareAndSet(false,true))open.decrementAndGet();}});}catch(InvocationTargetException e){throw e.getCause();}});
  var provider=new BackupEnvelopeEncryption.DataKeyProvider(){public BackupEnvelopeEncryption.KeyMaterial create(BackupEnvelopeEncryption.Access a,BackupEnvelopeEncryption.Scope s){return key();}public BackupEnvelopeEncryption.KeyMaterial unwrap(BackupEnvelopeEncryption.Access a,BackupEnvelopeEncryption.Scope s,String r,byte[] w){return key();}BackupEnvelopeEncryption.KeyMaterial key(){byte[] k=new byte[32];for(int i=0;i<32;i++)k[i]=(byte)i;return new BackupEnvelopeEncryption.KeyMaterial("kms-key-ref:synthetic-staging",new byte[]{1,2,3},k);}};
  cipher=new BackupEnvelopeEncryption(provider,(a,s,o)->true,1024);var r=repo();Scope scope=running();var p=payload(scope);UUID submit=id();
  var staged=r.stage(access(),submit,1,p,"stage");check(staged.event().version()==0&&staged.event().phase()==Phase.STAGED&&!staged.event().storeDispatchAuthorized(),"source_and_initial_event_commit_together_without_execution_grant");
  int n=envelopes.get();check(r.stage(access(),submit,1,p,"replay").replay()&&envelopes.get()==n,"identical_stage_replay_never_reencrypts_or_reverifies");
  check(Arrays.equals(repo().current(access(),scope).orElseThrow().source().payload().bytes(),p.bytes()),"new_repository_instance_recovers_exact_original_ciphertext");
  denied(()->r.stage(access(),id(),1,p,"changed"),"changed_submission_conflict");var different=new Scope(tenant,scope.assetId(),scope.runId(),1,id());denied(()->r.stage(access(),id(),1,payload(different),"replacement"),"one_original_envelope_per_attempt");
  denied(()->r.current(new Access(tenant,actor,2),scope),"current_authorization_required_for_reads");denied(()->r.stage(new Access(tenant,actor,2),submit,1,p,"revoked"),"current_authorization_required_for_replay");
  Scope badScope=running();var good=payload(badScope);byte[] corrupt=good.bytes();corrupt[corrupt.length-1]^=1;String h=HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(corrupt));long before=count("mop_backup_archive_submission");proofDenied(()->r.stage(access(),id(),1,BackupArchivePayload.parse(corrupt,h),"bad"),"digest_valid_but_aead_invalid_cannot_stage");check(count("mop_backup_archive_submission")==before,"verification_failure_no_source_or_receipt");
  var dispatch=new Dispatch(id(),"worker");UUID start=id();var started=r.startStore(access(),scope,start,0,dispatch,"start");check(started.event().requiresReadOnlyReconciliation()&&!started.event().storeDispatchAuthorized(),"started_task_requires_reconciliation_not_put_authority");
  r.markUnconfirmed(access(),scope,id(),1,dispatch,"unknown");denied(()->r.startStore(access(),scope,id(),2,new Dispatch(id(),"worker"),"blind"),"unknown_never_blindly_redispatched");
  check(r.startStore(access(),scope,start,0,dispatch,"old").event().version()==1&&r.current(access(),scope).orElseThrow().event().version()==2,"old_command_replays_original_receipt_not_latest_state");
  proofDenied(()->r.confirmNoDispatch(access(),scope,id(),2,dispatch,"sha256:"+"b".repeat(64),"unproven"),"arbitrary_proof_hash_rejected");check(r.current(access(),scope).orElseThrow().event().version()==2,"failed_proof_does_not_append_event");
  var reset=r.confirmNoDispatch(access(),scope,id(),2,dispatch,REF,"proof");check(reset.event().phase()==Phase.STAGED&&reset.event().dispatchCount()==1,"independent_synthetic_no_dispatch_proof_preserves_history");denied(()->r.startStore(access(),scope,id(),3,dispatch,"reuse"),"old_dispatch_id_cannot_be_reused");
  var fresh=new Dispatch(id(),"worker");r.startStore(access(),scope,id(),3,fresh,"new");UUID verifiedCommand=id();var verified=r.verifyObject(access(),scope,verifiedCommand,4,REF,"verify");check(verified.event().phase()==Phase.VERIFIED&&!verified.event().backupRunCompleted()&&!verified.event().versionRegistered(),"object_fact_never_registers_version_or_completes_run");check(RunDatabaseChecks.repo().current(tenant,scope.assetId(),scope.runId()).orElseThrow().state().state()==cn.mop.domain.backup.BackupRunState.State.RUNNING,"parent_run_unchanged");
  int oldProofs=proofs.get();check(r.verifyObject(access(),scope,verifiedCommand,4,REF,"again").replay()&&proofs.get()==oldProofs,"verified_command_replay_no_external_calls");denied(()->r.startStore(access(),scope,id(),5,new Dispatch(id(),"worker"),"terminal"),"verified_terminal_no_new_dispatch");
  Scope cas=running();r.stage(access(),id(),1,payload(cas),"cas");var latch=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var jobs=new ArrayList<Future<Boolean>>();for(int i=0;i<2;i++)jobs.add(pool.submit(()->{latch.await();try{repo().startStore(access(),cas,id(),0,new Dispatch(id(),"worker"),"cas");return true;}catch(DomainException e){if(e.status!=409)throw e;return false;}}));latch.countDown();int wins=0;for(var job:jobs)if(job.get(15,TimeUnit.SECONDS))wins++;check(wins==1,"independent_database_connections_one_cas_winner");}finally{pool.shutdownNow();}
  Scope orphan=running();var orphanPayload=payload(orphan);before=count("mop_backup_archive_submission");denied(()->{try(var c=RunDatabaseChecks.runtime.getConnection()){c.setAutoCommit(false);rawSource(c,orphan,orphanPayload);c.commit();}},"deferred_constraint_rejects_source_without_initial_event");check(count("mop_backup_archive_submission")==before,"deferred_failure_rolls_back_source");
  for(String table:List.of("mop_backup_archive_submission","mop_backup_archive_event"))for(String action:List.of("UPDATE "+table+" SET device_execution_authorized=false","DELETE FROM "+table,"TRUNCATE "+table))denied(()->{try(var c=RunDatabaseChecks.runtime.getConnection();var q=c.createStatement()){q.execute(action);}},"runtime_append_only_"+table+"_"+action.split(" ")[0]);
  Scope revokedScope=running();var revokedPayload=payload(revokedScope);AtomicBoolean revoked=new AtomicBoolean();var revokeDuringProof=new PostgresBackupArchiveRepository(tracked,(c,a,s,o)->{if(revoked.get())throw new DomainException(403,"REVOKED","synthetic");},(a,body)->{authenticate(body);revoked.set(true);},(a,source,event,action,ref)->{});before=count("mop_backup_archive_submission");denied(()->revokeDuringProof.stage(access(),id(),1,revokedPayload,"revoke_after_proof"),"revocation_after_external_verification_blocks_commit");check(count("mop_backup_archive_submission")==before,"revoked_stage_leaves_no_source");
  Scope changedScope=running();var changedPayload=payload(changedScope);UUID winner=id();var changeDuringProof=new PostgresBackupArchiveRepository(tracked,(c,a,s,o)->{},(a,body)->{authenticate(body);r.stage(access(),winner,1,body,"winner");},(a,source,event,action,ref)->{});denied(()->changeDuringProof.stage(access(),id(),1,changedPayload,"loser"),"stage_compare_again_after_external_verification");check(r.current(access(),changedScope).orElseThrow().source().submissionId().equals(winner),"concurrent_original_source_not_replaced");
  Scope staleProofScope=running();r.stage(access(),id(),1,payload(staleProofScope),"stale_proof");var staleDispatch=new Dispatch(id(),"worker");r.startStore(access(),staleProofScope,id(),0,staleDispatch,"start");var changeDuringObjectProof=new PostgresBackupArchiveRepository(tracked,(c,a,s,o)->{},(a,body)->authenticate(body),(a,source,event,action,ref)->{check(open.get()==0,"changed_evidence_check_outside_transaction");r.markUnconfirmed(access(),staleProofScope,id(),1,staleDispatch,"racing_unknown");});denied(()->changeDuringObjectProof.verifyObject(access(),staleProofScope,id(),1,REF,"stale"),"stale_external_proof_cannot_overwrite_new_event");check(r.current(access(),staleProofScope).orElseThrow().event().phase()==Phase.VERIFY_REQUIRED,"newer_unknown_fact_preserved");
  check(open.get()==0,"all_repository_connections_closed");System.out.println("TOTAL_PASS="+checks+" SYNTHETIC_PROOF_ADAPTERS_ONLY=true NO_PROVIDER_PUT=true NO_DEVICE_EXECUTION=true");
 }
 static final class RunDatabaseChecks {
 static PGSimpleDataSource runtime,migrator;static UUID tenant;static int checks;
 static final String REF="sha256:"+"a".repeat(64);
 static PGSimpleDataSource source(String user,String password){var s=new PGSimpleDataSource();s.setURL(System.getenv("SPRING_DATASOURCE_URL"));s.setUser(user);s.setPassword(password);return s;}
 static void check(boolean value,String name){if(!value)throw new AssertionError(name);checks++;System.out.println("PASS "+name);}
 static PostgresBackupRunRepository repo(){return new PostgresBackupRunRepository(runtime,(c,t,a,r)->{if(!tenant.equals(t))throw new DomainException(403,"SYNTHETIC_SCOPE_DENIED","synthetic");},(c,r,s,l)->{if(!"worker".equals(l.owner()))throw new DomainException(409,"SYNTHETIC_START_DENIED","synthetic");},(c,r,s,o,f,v,ref)->{if(!REF.equals(ref))throw new DomainException(409,"SYNTHETIC_RESULT_UNVERIFIED","synthetic");});}
 static PostgresBackupDeviceLeaseRepository leases(){return new PostgresBackupDeviceLeaseRepository(runtime,(c,t,a,r)->{if(!tenant.equals(t))throw new DomainException(403,"SYNTHETIC_SCOPE_DENIED","synthetic");},(c,s,ref)->{if(!REF.equals(ref))throw new DomainException(409,"SYNTHETIC_STOP_UNVERIFIED","synthetic");});}
 static UUID asset()throws Exception{UUID id=UUID.randomUUID();try(var c=migrator.getConnection();var s=c.prepareStatement("INSERT INTO mop_asset(id,tenant_id,name,type,management_ip,site_id,source) SELECT ?,tenant_id,?,'router','192.0.2.1',id,'SYNTHETIC_RUN_TEST' FROM mop_site WHERE tenant_id=? ORDER BY id LIMIT 1")){s.setObject(1,id);s.setString(2,"synthetic-run-"+id);s.setObject(3,tenant);if(s.executeUpdate()!=1)throw new AssertionError("site fixture missing");}return id;}
 static PostgresBackupRunRepository.LeaseClaim acquire(UUID asset,long millis){var r=leases().acquire(tenant,asset,UUID.randomUUID(),"worker",Duration.ofMillis(millis),"lease");return new PostgresBackupRunRepository.LeaseClaim(r.state().requestId(),"worker",r.state().fencingToken());}
 static void release(UUID asset,PostgresBackupRunRepository.LeaseClaim claim){var s=leases().current(tenant,asset,claim.requestId()).orElseThrow().state();leases().release(tenant,asset,claim.requestId(),claim.owner(),claim.fencingToken(),s.version(),REF,"release");}
 interface Attempt{void run()throws Exception;}
 static void denied(Attempt action,String name)throws Exception{try{action.run();}catch(DomainException e){if(!Set.of(400,403,404,409).contains(e.status))throw e;check(true,name);return;}catch(SQLException e){if(!Set.of("23514","23505","42501").contains(e.getSQLState()))throw e;check(true,name);return;}throw new AssertionError("accepted "+name);}
 static long count()throws Exception{try(var c=runtime.getConnection();var s=c.createStatement();var r=s.executeQuery("SELECT count(*) FROM mop_backup_run_event")){r.next();return r.getLong(1);}}
 static UUID id(){return UUID.randomUUID();}

 }
}
